package agentimport

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/factoryaidroid"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// factoryImporter imports Factory AI Droid transcripts
// (~/.factory/sessions/<repo>/<id>.jsonl). Droid wraps each message in an
// envelope ({"type":"message","id":..,"message":{...}}); token usage is
// subagent-aware and the model lives in an adjacent <id>.settings.json.
type factoryImporter struct{}

func (factoryImporter) Name() string { return string(agent.AgentNameFactoryAIDroid) }

func (factoryImporter) AgentType() types.AgentType { return agent.AgentTypeFactoryAIDroid }

// Discover returns Factory transcript files for the repo modified within the
// lookback window.
func (factoryImporter) Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error) {
	dir, err := resolveDir(repoRoot, overridePath, "factory", (&factoryaidroid.FactoryAIDroidAgent{}).GetSessionDir)
	if err != nil {
		return nil, err
	}
	return discoverSessionFiles(dir, now, sessionFilter, jsonlSessionResolver(".jsonl", identitySessionID))
}

// SplitTurns produces one Turn per user-prompt envelope, bounded by the next.
// Token usage is delegated to the Factory agent; spawned-subagent usage comes
// back as a cumulative snapshot and is rescoped to a per-turn delta by
// splitLineTurns (see rescopeSubagentTokensToDeltas). The model is read once
// from the session's adjacent settings file. Droid
// envelopes carry no per-message timestamp (the agent stamps events with
// time.Now() at hook time), so every turn falls back to the transcript file's
// modtime — the same fallback the Gemini importer uses.
func (factoryImporter) SplitTurns(sf SessionFile, full []byte) ([]Turn, error) {
	subagentsDir := filepath.Join(filepath.Dir(sf.Path), sf.SessionID, "subagents")
	model := factoryaidroid.ExtractModelFromTranscript(sf.Path)
	var createdAt time.Time
	if info, statErr := os.Stat(sf.Path); statErr == nil {
		createdAt = info.ModTime()
	}
	ag := &factoryaidroid.FactoryAIDroidAgent{}
	return splitLineTurns(splitRawLines(full),
		func(raw []byte) bool { _, ok := factoryPromptText(raw); return ok },
		func(rawLines [][]byte, start, _ int, truncated []byte) (*Turn, error) {
			tokens, err := ag.CalculateTotalTokenUsage(truncated, start, subagentsDir)
			if err != nil {
				return nil, fmt.Errorf("token usage: %w", err)
			}
			var env struct {
				ID string `json:"id"`
			}
			if err := json.Unmarshal(rawLines[start], &env); err != nil {
				//nolint:nilerr // skip defensively; the line already parsed in factoryPromptText
				return nil, nil
			}
			prompt, _ := factoryPromptText(rawLines[start])
			return &Turn{UUID: env.ID, Prompt: prompt, Model: model, CreatedAt: createdAt, Tokens: tokens}, nil
		})
}

// factoryPromptText reports whether a raw Droid JSONL line is a user-prompt
// message and returns its text. Droid tags the role inside the inner message;
// tool_result user messages carry no extractable text and return false.
func factoryPromptText(raw []byte) (string, bool) {
	var env struct {
		Type    string          `json:"type"`
		Message json.RawMessage `json:"message"`
	}
	if err := json.Unmarshal(raw, &env); err != nil || env.Type != "message" {
		return "", false
	}
	var role struct {
		Role string `json:"role"`
	}
	if err := json.Unmarshal(env.Message, &role); err != nil || role.Role != transcript.TypeUser {
		return "", false
	}
	text := transcript.ExtractUserContent(env.Message)
	if text == "" {
		return "", false
	}
	return text, true
}

package cli

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// entireManagedAgentHelpSkillMarker tags the agent-help skill files Entire owns,
// so re-running setup can safely update them and never clobbers a hand-written
// file at the same path.
const entireManagedAgentHelpSkillMarker = "ENTIRE-MANAGED AGENT-HELP SKILL v1"

// setupOptionalAgentHelpSkill installs the stable "how to use entire" skill for
// ag when opts.AgentHelpSkill is set. The skill body is near-immutable — it only
// points the agent at `entire agent-help` — so re-running enable reports
// "unchanged" rather than churning a diff.
func setupOptionalAgentHelpSkill(ctx context.Context, w io.Writer, ag agent.Agent, opts EnableOptions) error {
	if !opts.AgentHelpSkill {
		return nil
	}
	result, err := scaffoldAgentHelpSkill(ctx, ag)
	if err != nil {
		return fmt.Errorf("failed to scaffold %s agent-help skill: %w", ag.Name(), err)
	}
	reportAgentHelpSkillScaffold(w, ag, result)
	return nil
}

func setupOptionalAgentHelpSkillForNames(ctx context.Context, w io.Writer, names []string, opts EnableOptions) error {
	return setupOptionalSkillForNames(ctx, w, names, opts.AgentHelpSkill, setupOptionalAgentHelpSkill, opts)
}

func scaffoldAgentHelpSkill(ctx context.Context, ag agent.Agent) (managedScaffoldResult, error) {
	relPath, content, ok := agentHelpSkillTemplate(ag.Name())
	if !ok {
		return managedScaffoldResult{Status: managedScaffoldUnsupported}, nil
	}

	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails in tests
		if err != nil {
			return managedScaffoldResult{}, fmt.Errorf("failed to get current directory: %w", err)
		}
	}

	targetPath := filepath.Join(repoRoot, relPath)
	return writeManagedScaffold(targetPath, relPath, content, isManagedAgentHelpSkill)
}

func isManagedAgentHelpSkill(data []byte) bool {
	return bytes.Contains(data, []byte(entireManagedAgentHelpSkillMarker))
}

func reportAgentHelpSkillScaffold(w io.Writer, ag agent.Agent, result managedScaffoldResult) {
	switch result.Status {
	case managedScaffoldCreated:
		fmt.Fprintf(w, "  ✓ Installed %s agent-help skill\n", ag.Type())
		fmt.Fprintf(w, "    %s\n", result.RelPath)
	case managedScaffoldUpdated:
		fmt.Fprintf(w, "  ✓ Updated %s agent-help skill\n", ag.Type())
		fmt.Fprintf(w, "    %s\n", result.RelPath)
	case managedScaffoldSkippedConflict:
		fmt.Fprintf(w, "  Skipped %s agent-help skill (unmanaged file exists)\n", ag.Type())
		fmt.Fprintf(w, "    %s\n", result.RelPath)
	case managedScaffoldUnsupported:
		fmt.Fprintf(w, "  Agent-help skill is not supported for %s\n", ag.Type())
		fmt.Fprintf(w, "    %s discovers entire via `%s` (passive — no skill file needed)\n", ag.Type(), agentHelpCommand)
	case managedScaffoldUnchanged:
		fmt.Fprintf(w, "  Agent-help skill already installed for %s\n", ag.Type())
		fmt.Fprintf(w, "    %s\n", result.RelPath)
	}
}

func agentHelpSkillTemplate(agentName types.AgentName) (string, []byte, bool) {
	switch agentName {
	case agent.AgentNameClaudeCode:
		return filepath.Join(".claude", "skills", "entire", "SKILL.md"), []byte(strings.TrimSpace(claudeAgentHelpSkillTemplate) + "\n"), true
	case agent.AgentNameCodex:
		return filepath.Join(".codex", "agents", "entire.toml"), []byte(strings.TrimSpace(codexAgentHelpSkillTemplate) + "\n"), true
	case agent.AgentNameGemini:
		return filepath.Join(".gemini", "agents", "entire.md"), []byte(strings.TrimSpace(geminiAgentHelpSkillTemplate) + "\n"), true
